push.css:
.fxs .tg{--pr:15px;--pushA:#E9C873;--pushB:#0A1B22;--pushC:#F4DC96;--rim:#E9C873;--rimD:#0A1B22;--pushFace:#0A1C23}
.fxs .push.tg{width:300px;height:164px;box-shadow:0 0 0 2px #E9C873,0 0 0 4.5px #0A1B22,0 0 0 6px #B48A3A,0 7px 0 6px #6E5216,0 8.5px 0 6px #0A1B22,
  0 0 18px 3px rgba(38,255,130,.2),0 0 50px 16px rgba(38,255,130,.1),0 22px 34px rgba(0,0,0,.5)}
.fxs .push.tg span{color:transparent;text-shadow:none}
.fxs .push.tg::after{border-color:rgba(107,255,174,.9)}
.fxs .pshadow.tg{width:300px}
.fxs .tg .tgf{position:absolute;left:0;top:0;width:300px;height:164px;border-radius:15px;overflow:hidden;pointer-events:none;font-style:normal}
.fxs .tg .tgf svg{display:block;width:300px;height:164px}
.fxs .tg .tgd{position:absolute;left:-50px;top:-50px;width:400px;height:264px;pointer-events:none;z-index:3;font-style:normal}
.fxs .tg .tgd svg{display:block;width:400px;height:264px;overflow:visible}
.fxs .tg .tgH{animation:fxtgH 1.4s ease-in-out infinite alternate}
@keyframes fxtgH{from{opacity:.06}to{opacity:.16}}
.fxs .tg .tgs{opacity:0;transform-box:fill-box;transform-origin:50% 50%;animation:fxtgS 1.7s ease-out infinite}
@keyframes fxtgS{0%{opacity:0;transform:translate(0,0) scale(1)}6%{opacity:1}40%{opacity:0;transform:translate(var(--x),var(--y)) scale(.4)}100%{opacity:0;transform:translate(var(--x),var(--y)) scale(.4)}}
.fxs .tap.tg{color:#F4DC96;text-shadow:0 2px 0 #0A1B22,0 0 12px rgba(38,255,130,.85)}
.fxs .pressed.tg{width:300px;height:164px;margin:-82px 0 0 -150px;border-radius:15px;background:#0A1C23;box-shadow:0 0 0 2px #E9C873,0 0 0 4.5px #0A1B22,0 0 0 6px #B48A3A,0 7px 0 6px #6E5216,0 0 18px 3px rgba(38,255,130,.2);animation-name:fxtgPress,fxfxH}
@keyframes fxtgPress{0%{transform:scale(1)}22%{transform:scale(.92)}45%{transform:scale(1.05)}100%{transform:scale(1.3);opacity:0}}
.fxs .clips.tg{position:absolute;z-index:4;left:50%;top:calc(50% - 40px);width:0;height:0}
.fxs .clips.tg .tgb{position:absolute;left:-300px;top:-230px;width:600px;height:460px;overflow:visible;visibility:hidden;animation:fxtgBolt .5s step-end .06s both}
@keyframes fxtgBolt{0%{visibility:visible}16%{visibility:hidden}24%{visibility:visible}52%,100%{visibility:hidden}}
.fxs .clips.tg i{position:absolute;opacity:0;left:calc(var(--z) / -2);top:calc(var(--z) / -2);width:var(--z);height:var(--z);border-radius:50%;animation:fxtgFly 1.1s cubic-bezier(.15,.7,.3,1) calc(var(--d) + .08s) both}
.fxs .clips.tg .s{background:radial-gradient(circle,#F4FFF8 0 30%,rgba(107,255,174,.9) 50%,rgba(38,255,130,0) 72%)}
.fxs .clips.tg .w{background:radial-gradient(circle,#FFFFFF 0 35%,rgba(244,255,248,.6) 55%,rgba(244,255,248,0) 72%)}
.fxs .clips.tg .lf{left:-190px;top:-2px;width:380px;height:4px;border-radius:2px;background:linear-gradient(90deg,rgba(107,255,174,0),#F4FFF8 50%,rgba(107,255,174,0));animation:fxtgLf .45s ease-out .06s both}
.fxs .clips.tg .ring{left:-150px;top:-82px;width:300px;height:164px;border-radius:15px;border:4px solid rgba(107,255,174,.9);box-shadow:0 0 18px rgba(38,255,130,.6);animation:fxtgRing .8s ease-out .1s forwards}
.fxs .clips.tg .ring.b{border-width:2.5px;animation-delay:.26s}
@keyframes fxtgFly{0%{opacity:0;transform:translate(0,0) scale(.4)}10%{opacity:1}60%{opacity:1;transform:translate(var(--x),var(--y)) scale(1)}100%{opacity:0;transform:translate(calc(var(--x) * 1.1),calc(var(--y) + 40px)) scale(.6)}}
@keyframes fxtgLf{0%{opacity:0;transform:scaleX(.1)}30%{opacity:1;transform:scaleX(1)}100%{opacity:0;transform:scaleX(1.3)}}
@keyframes fxtgRing{0%{opacity:.9;transform:scale(.92)}100%{opacity:0;transform:scale(1.6)}}
@media (prefers-reduced-motion:reduce){.fxs .tg .tgH,.fxs .tg .tgs{animation:none}
.fxs .tg .tgs,.fxs .clips.tg{display:none}}
