.fxs .rb.t-tengel{--hdB:1px solid rgba(217,180,90,.20);--cardO:1px solid rgba(217,180,90,.14);--zBg:#0D242D;--zB:1px solid rgba(217,180,90,.20);--sep:1px solid rgba(217,180,90,.20);--rs:12px;--nR:7px;--w2B:1.5px solid #6F8C93;--tagBg:rgba(217,180,90,.08);--tagInk:#F4DC96;--tagLine:rgba(217,180,90,.42);--bg:#0A1B22;--ink:#E8F0F1;--sub:#A6BEC3;--card:linear-gradient(160deg,#153B47,#10303A);--cardB:1px solid rgba(217,180,90,.42);--cardS:0 18px 40px rgba(0,0,0,.38);--radius:16px;--font:"BIZ UDPGothic";--dfont:"Dela Gothic One";--dw:400;--logo:#E9C873;--logoS:none;--hd:#0A1B22;--hdInk:#E8F0F1;--acc:#F4DC96;--h1:#F4DC96;--coin:linear-gradient(180deg,#FBE9B0,#D9B45A);--coinInk:#0A1B22;--rbFace:#153B47}
.fxs .rb.t-tengel{background-image:radial-gradient(70% 28% at 50% 12%,rgba(92,202,214,.13),transparent 70%),repeating-linear-gradient(90deg,rgba(217,180,90,.045) 0 1px,transparent 1px 36px)}
.fxs .rb.t-tengel .logo{background:linear-gradient(180deg,#FBE9B0 0%,#E2BF66 46%,#A47A2C 100%);-webkit-background-clip:text;background-clip:text;color:transparent}
